export {portfolio,reverseSets};
export const complete=x=>({...x,recommendationSet:buildRecommendations(x)});
export const baseline=(options={})=>complete(base(options));
export const scenario=o=>complete(sourceScenario(o));
export const defect=()=>complete(sourceDefect());
export function synchronize(x){const s=x.recommendationSet,rs=s.recommendations;s.primaryRecommendationIds=rs.slice(0,10).map(r=>r.recommendationId);s.recommendationGroups=[{groupCode:'CASH_FLOW',recommendationIds:rs.map(r=>r.recommendationId)}];s.confidence=weakest(x.productSelection.confidence,...rs.map(r=>r.confidence));s.summary={...s.summary,recommendationCount:rs.length,primaryCount:s.primaryRecommendationIds.length,suppressedCount:s.suppressedRecommendations.length,byPriority:Object.fromEntries(RECOMMENDATION_POLICY.priorityOrder.map(p=>[p,rs.filter(r=>r.priority===p).length])),byActionability:Object.fromEntries(RECOMMENDATION_POLICY.actionabilityOrder.map(p=>[p,rs.filter(r=>r.actionability===p).length]))};return x;}
export function consumer(specs=[{}]){const x=baseline(),template=x.recommendationSet.recommendations[0];x.recommendationSet.recommendations=specs.map((spec,i)=>{const d=RECOMMENDATION_REGISTRY.definitions.find(d=>d.code===(spec.definitionCode??'EXPLAIN_CURRENT_LOSS'));if(!d)throw Error('Unknown fixture code');return {...structuredClone(template),...structuredClone(d),definitionCode:d.code,definitionVersion:d.version,recommendationId:id('recommendation','synthetic-plan-contract',d.code,i),subjectKey:'synthetic-plan-subject-'+i,titleRu:d.titleRu,actionSummaryRu:d.actionSummaryRu,stepsRu:[...d.stepsRu],completionEvidenceRu:[...d.completionEvidenceRu],whatPrescoreWillRecheckRu:d.whatPrescoreWillRecheckRu,verificationCriteria:d.verificationCriteriaTemplate.map(v=>({...v,subjectKey:'synthetic-plan-subject-'+i})),expectedAnalyticalEffects:[...d.expectedAnalyticalEffects],category:d.category,actionType:d.actionType,remediability:d.remediability,effort:'MEDIUM',priority:'P2_MEDIUM',actionability:'ACTIONABLE',confidence:'HIGH',prerequisiteRecommendationIds:[],riskFindingIds:[],riskFactIds:[],contextRelationIds:[],contextFactIds:[],assessmentDriverIds:[],assessmentLimitationIds:[],capacityReferenceIds:[],portfolioObligationIds:[],productFamilies:[],productDataRequirementCodes:[],sourceIds:['synthetic-plan-source'],...spec};});return synchronize(x);}
export function dependency(specs){const x=consumer(specs);for(let i=1;i<x.recommendationSet.recommendations.length;i++)x.recommendationSet.recommendations[i].prerequisiteRecommendationIds=[x.recommendationSet.recommendations[i-1].recommendationId];return x;}
